<?php
declare(strict_types=1);
$config=require __DIR__.'/config/config.php';$message='';$error='';
if(session_status()!==PHP_SESSION_ACTIVE){session_name($config['session_name']??'NACOS_VOTE_SESSION');session_set_cookie_params(['httponly'=>true,'secure'=>isset($_SERVER['HTTPS']),'samesite'=>'Lax']);session_start();}
if(empty($_SESSION['_setup_csrf']))$_SESSION['_setup_csrf']=bin2hex(random_bytes(32));
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['_setup_csrf'],$_POST['_csrf']??'')){http_response_code(419);$error='Security token expired. Reload setup.php and try again.';}
 else{
  try{$d=$config['db'];$pdo=new PDO("mysql:host={$d['host']};charset={$d['charset']}",$d['user'],$d['pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$pdo->exec("CREATE DATABASE IF NOT EXISTS `".str_replace('`','',$d['name'])."` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");$pdo->exec('USE `'.str_replace('`','',$d['name']).'`');$sql=file_get_contents(__DIR__.'/database/schema.sql');$sql=preg_replace('/^CREATE DATABASE.*?;\s*USE .*?;\s*/s','',$sql);foreach(array_filter(array_map('trim',explode(';',$sql))) as $statement)$pdo->exec($statement);$email=filter_var($_POST['admin_email']??'',FILTER_VALIDATE_EMAIL);$pw=$_POST['admin_password']??'';$name=trim($_POST['admin_name']??'');if(!$name||!$email||strlen($pw)<12)throw new RuntimeException('Provide a valid name, email and an admin password of at least 12 characters.');$q=$pdo->prepare("SELECT id FROM users WHERE role='admin' LIMIT 1");$q->execute();if($q->fetch())throw new RuntimeException('Installation is already protected by an existing administrator account. Delete or rename setup.php.');$s=$pdo->prepare("INSERT INTO users(full_name,email,password_hash,role,is_verified) VALUES(?,?,?,'admin',1)");$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);$message='Installation completed. Sign in with the administrator credentials you just created. Delete or rename setup.php now.';}catch(Throwable $e){$error=$e->getMessage();}
 }
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>NACOS installer</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="public/assets/style.css" rel="stylesheet"></head><body><main class="container py-5"><div class="auth-wrap card p-4 p-md-5"><div class="eyebrow">First-time setup</div><h1 class="h3 fw-bold">Install NACOS E-Voting</h1><p class="text-secondary">Create database tables and the first administrator account using the database settings in config/config.php.</p><?php if($message):?><div class="alert alert-success"><?=htmlspecialchars($message)?></div><a class="btn btn-primary" href="index.php?page=login">Go to sign in</a><?php else:?><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($_SESSION['_setup_csrf'])?>"><div class="mb-3"><label class="form-label">Administrator name</label><input class="form-control" name="admin_name" value="NACOS Administrator" required></div><div class="mb-3"><label class="form-label">Administrator email</label><input class="form-control" type="email" name="admin_email" required></div><div class="mb-3"><label class="form-label">Administrator password (12+ characters)</label><input class="form-control" type="password" name="admin_password" minlength="12" required></div><button class="btn btn-primary w-100">Install application</button></form><?php endif;?></div></main></body></html>
